/**
 * Decodes the pre-bundled `@modelscript/fea-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getFeaStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(FEA_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
